SELECT id, service, level, latency_ms, status_code, payload_json, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, context['region'] AS region, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, SIZE(context) AS num_context, COALESCE(context['region'], 'direct') AS region_or_default FROM app_logs WHERE level = 'DEBUG'
